void initBandStopFilter(Biquad *filter, float fs, float notchFreq, float Q){
    // 计算数字频率 w0
    float w0 = 2.0 * M_PI * notchFreq / fs; // 设计数字频率 (radians/sample)

    // 计算中间变量 (直接使用数字频率 w0)
    float cosw = cos(w0);
    float alpha = sin(w0) / (2.0 * Q); // Q值越大，alpha越小，陷波越窄

    // 计算未归一化滤波器系数 (标准的陷波/峰值滤波器形式)
    float b0_raw = 1.0;
    float b1_raw = -2.0 * cosw;
    float b2_raw = 1.0;
    float a0_raw = 1.0 + alpha;
    float a1_raw = -2.0 * cosw;
    float a2_raw = 1.0 - alpha;

    // 归一化滤波器系数
    filter->b0 = b0_raw / a0_raw;
    filter->b1 = b1_raw / a0_raw;
    filter->b2 = b2_raw / a0_raw;
    filter->a1 = a1_raw / a0_raw;
    filter->a2 = a2_raw / a0_raw;

    // 初始化状态
    filter->x1 = 0.0;
    filter->x2 = 0.0;
    filter->y1 = 0.0;
    filter->y2 = 0.0;

    // 可选：打印系数进行验证
}

// 处理单个样本
float processSample(Biquad *filter, float input){
    float output = filter->b0 * input + filter->b1 * filter->x1 + filter->b2 * filter->x2 - filter->a1 * filter->y1 - filter->a2 * filter->y2;
    // 更新状态
    filter->x2 = filter->x1;
    filter->x1 = input;
    filter->y2 = filter->y1;
    filter->y1 = output;
    return output;
}
