// 初始化二阶低通滤波器
// fs: 采样频率(Hz)
// fc: 截止频率(Hz)
// Q: 品质因数(建议0.707为巴特沃斯响应)
void initLowPassFilter(BiquadLPF *filter, float fs, float fc, float Q){
    // 参数有效性检查
    if(fc >= fs / 2){
        fc = fs / 2.1f; // 防止超过奈奎斯特频率
    }
    if(Q < 0.1f){
        Q = 0.1f;
    }
    if(Q > 10.0f){
        Q = 10.0f;
    }

    // 预畸变处理
    float omega = 2.0f * M_PI * fc / fs;   // 数字角频率
    float alpha = sin(omega) / (2.0f * Q); // 带宽参数
    float cosw = cos(omega);

    // 计算双二阶系数
    float a0 = 1.0f + alpha;
    filter->b0 = (1.0f - cosw) / 2.0f / a0;
    filter->b1 = (1.0f - cosw) / a0;
    filter->b2 = filter->b0;
    filter->a1 = -2.0f * cosw / a0;
    filter->a2 = (1.0f - alpha) / a0;

    // 初始化状态变量
    filter->x1 = 0.0f;
    filter->x2 = 0.0f;
    filter->y1 = 0.0f;
    filter->y2 = 0.0f;
}

// 带保护的滤波处理函数
float processLPF(BiquadLPF *filter, float input){
    // 输入有效性检查
    //    if(isnan(input)) input = 0.0f;
    //    input = fmaxf(fminf(input, 1.0f), -1.0f); // 假设信号范围±1V

    // 差分方程计算
    float output = filter->b0 * input + filter->b1 * filter->x1 + filter->b2 * filter->x2 - filter->a1 * filter->y1 - filter->a2 * filter->y2;

    // 状态变量保护
    output = fmaxf(fminf(output, 1.0f), -1.0f);

    // 更新延迟线
    filter->x2 = filter->x1;
    filter->x1 = input;
    filter->y2 = filter->y1;
    filter->y1 = output;

    return output;
}

// --- 需要您根据实际情况定义的参数 ---
#define IMU_SAMPLING_FREQ_HZ 500.0f // <<< 修改为您IMU数据的实际采样频率 (Hz)
// -------------------------------------
#define FILTER_CUTOFF_FREQ_HZ 0.18f // 期望的截止频率 (Hz)
// 计算滤波器系数 (这些系数在程序启动时计算一次即可)
// 注意：在某些Keil版本或编译器设置下，直接在全局const float中进行复杂计算可能有限制
// 更安全的做法是在初始化函数中计算并存储到非常量变量或通过宏进行简单的浮点计算
// 这里为了代码清晰，假设可以直接计算或在初始化阶段完成计算并赋值给常量指针等
// 实际应用中，如果遇到问题，请将计算逻辑移到初始化函数中。

// 计算中间变量 alpha = fs / (PI * fc)
// 使用宏进行编译期计算 (如果可能且支持) 或运行时计算
// 计算中间变量 alpha = fs / (PI * fc)
#define ALPHA_CALC (IMU_SAMPLING_FREQ_HZ / (M_PI * FILTER_CUTOFF_FREQ_HZ))

// 滤波器系数 (y[n] = a0*x[n] + a1*x[n-1] + b1*y[n-1])
static const float FILTER_A0 = ALPHA_CALC / (1.0f + ALPHA_CALC);
static const float FILTER_A1 = -FILTER_A0;
// *** 修正这里的 FILTER_B1 计算 ***
static const float FILTER_B1 = (ALPHA_CALC - 1.0f) / (ALPHA_CALC + 1.0f);
// 或者等价地写成 (f_s - PI*f_c) / (f_s + PI*f_c)
// static const float FILTER_B1 = (IMU_SAMPLING_FREQ_HZ - M_PI * FILTER_CUTOFF_FREQ_HZ) / (IMU_SAMPLING_FREQ_HZ + M_PI * FILTER_CUTOFF_FREQ_HZ);

// --------------------------------------------------------------
// 滤波器状态结构体：需要为每个独立的信号保存前一个输入和前一个输出

// --------------------------------------------------------------
// 函数：初始化滤波器状态
// 在系统启动或需要重置滤波器时调用
void HighPassFilter_Init(FirstOrderHighPassFilterState_t *state){
    // 初始化历史数据为0。
    // 注意：这可能在滤波器开始工作时产生一个短暂的瞬态响应，
    // 特别是当第一个输入值非零时。对于移除DC偏移，这个瞬态通常是可接受的。
    // 更平滑的启动可能需要特殊的初始化方法，例如用第一个输入值填充历史状态，
    // 但这会略微增加复杂度。对于多数IMU应用，初始化为0即可。
    state->prev_input = 0.0f;
    state->prev_output = 0.0f;
}

// --------------------------------------------------------------
// 函数：处理单个输入样本并获取滤波后的输出
// 每个新的IMU数据点到来时，为每个轴调用此函数
// 参数:
//   state: 指向对应信号的滤波器状态结构体
//   current_input: 当前时刻的原始输入值 (例如，当前的加速度计X值)
// 返回值:
//   当前时刻的滤波输出值
float HighPassFilter_Process(FirstOrderHighPassFilterState_t *state, float current_input){
    // 应用差分方程: y[n] = a0*x[n] + a1*x[n-1] + b1*y[n-1]
    float current_output = FILTER_A0 * current_input + FILTER_A1 * state->prev_input + FILTER_B1 * state->prev_output;

    // 更新滤波器状态，保存当前输入和输出，以便下次使用
    state->prev_input = current_input;
    state->prev_output = current_output;

    return current_output;
}